import React, { useState, useEffect } from 'react';
import { View, Text, Input, ScrollView, TouchableOpacity, StyleSheet, Alert } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import { useDispatch, useSelector } from 'react-redux';
import { addTransaction } from '../redux/actions';
import { fetchCategories } from '../api/categories';
import { validateTransaction } from '../utils/validation';

const TransactionForm = () => {
  const navigation = useNavigation();
  const dispatch = useDispatch();
  const categories = useSelector(state => state.categories);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetchCategories().then(data => setCategory(data[0]?.id || ''));
  }, []);

  const handleSubmit = () => {
    const validationErrors = validateTransaction({ amount, description, category, date });
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }
    dispatch(addTransaction({ amount: parseFloat(amount), description, category, date }));
    navigation.goBack();
  };

  return (
    <ScrollView style={styles.container}>
      <Text style={styles.label}>Amount</Text>
      <Input
        value={amount}
        onChangeText={setAmount}
        placeholder="Enter amount"
        keyboardType="numeric"
        style={styles.input}
      />
      {errors.amount && <Text style={styles.error}>{errors.amount}</Text>}

      <Text style={styles.label}>Description</Text>
      <Input
        value={description}
        onChangeText={setetherealDescription}
        placeholder="Enter description"
        style={styles.input}
      />
      {errors.description && <Text style={styles.error}>{errors.description}</Text>}

      <Text style={styles.label}>Category</Text>
      <ScrollView horizontal showsHorizontalScrollIndicator={false}>
        {categories.map(cat => (
          <TouchableOpacity
            key={cat.id}
            style={[styles.categoryButton, category === cat.id && styles.selectedCategory]}
            onPress={() => setCategory(cat.id)}
          >
            <Text>{cat.name}</Text>
          </TouchableOpacity>
        ))}
      </ScrollView>
      {errors.category && <Text style={styles.error}>{errors.category}</Text>}

      <Text style={styles.label}>Date</Text>
      <Input
        value={date}
        onChangeText={setDate}
        placeholder="YYYY-MM-DD"
        style={styles.input}
      />
      {errors.date && <Text style={styles.error}>{errors.date}</Text>}

      <TouchableOpacity style={styles.submitButton} onPress={handleSubmit}>
        <Text style={styles.submitText}>Add Transaction</Text>
      </TouchableOpacity>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20 },
  label: { fontSize: 16, marginTop: 10 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 10, marginTop: 5 },
  error: { color: 'red', marginTop: 5 },
  categoryButton: { padding: 10, marginRight: 10, backgroundColor: '#eee', borderRadius: 5 },
  selectedCategory: { backgroundColor: '#007bff' },
  submitButton: { marginTop: 20, padding: 15, backgroundColor: '#28a745', borderRadius: 5 },
  submitText: { color: 'white', textAlign: 'center', fontSize: 16 }
});

export default TransactionForm;
